// Package runner is the remote half of gatehaul: runner.sh, embedded in the
// binary, and the Client that talks to it over a host.Transport.
//
// # Wire format (protocol GATEHAUL1)
//
// The remote command is always "bash -s". Its stdin is, in this order:
//
//  1. The preamble, generated by Preamble: a bash function followed by one line
//     that calls it, so that bash has parsed the whole preamble before it
//     reads anything else. The preamble prints "GATEHAUL1 HELLO <version>"
//     first (this line is what proves that the remote script started), then
//     reads exactly <len> bytes of runner with LC_ALL=C read -N (head -c may
//     read past its count on a pipe), checks that a script can be executed from
//     <root> (a noexec mount is refused with the code "noexec"), installs the
//     runner as <root>/runner-<version>.sh if it is missing or its sha256 is
//     wrong (write to a .tmp, check its sha256, then mv: one winner), and execs
//     it with GATEHAUL_ROOT set. The rest of stdin is the runner's.
//  2. The runner itself: <len> bytes of runner.sh.
//  3. The request header: a line "GATEHAUL1 <subcommand>", then "key=value"
//     lines, then an empty line. Values match [A-Za-z0-9._:,/+=-]*; free text
//     (the command, a grep pattern) is base64 in a key ending in "_b64". The
//     runner validates every value before using it, and never evaluates one.
//  4. The payload, for submit only: exactly bundle_len bytes of git bundle.
//
// The runner's stdout may start with noise from the remote shell. The
// controller skips everything before the HELLO line, then expects:
//
//	GATEHAUL1 BEGIN
//	<one line of JSON>
//	GATEHAUL1 END <rc>
//
// rc 0 means the JSON is the subcommand's response; any other rc means it is
// an ErrorResponse. A stream with HELLO but without END was cut: for submit,
// the outcome is unknown (the job may exist), and the controller never
// resubmits blindly; it tells the user to wait on the id it chose.
//
// # Remote layout
//
// See docs/SPEC.md §5. <root> is /workspaces/.gatehaul on codespaces and a
// temporary directory with the fake backend.
package runner

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"regexp"
	"time"
)

// Marker starts every protocol line.
const Marker = "GATEHAUL1"

// Schema is the version of every JSON document the runner writes.
const Schema = 1

// Subcommands of runner.sh.
const (
	CmdProbe  = "probe"
	CmdSubmit = "submit"
	CmdWait   = "wait"
	CmdLog    = "log"
	CmdCancel = "cancel"
	CmdGC     = "gc"
	CmdPatch  = "patch" // the patch of a finished gen job (M3)
)

// Limits shared by both sides.
const (
	MaxWaitSlice   = 60 * time.Second // one wait call; the controller loops
	MaxLogChunk    = 100 << 10        // bytes of log per response
	MaxBundleBytes = 2 << 30          // the runner refuses bigger bundles
	MaxPatchBytes  = 8 << 20          // the runner refuses to send a bigger patch
	MaxLogFile     = 16 << 20         // a job that writes more than this is stopped (failed, truncated)
)

// IDPattern is a job id: the host number, then a ULID (Crockford base32).
var IDPattern = regexp.MustCompile(`^[1-9][0-9]{0,3}-[0-9A-HJKMNP-TV-Z]{26}$`)

// KeyPattern is a branch key (docs/SPEC.md §5): a slug, then 6 hex digits of
// the sha256 of the full ref name.
var KeyPattern = regexp.MustCompile(`^[a-z0-9-]{1,32}-[0-9a-f]{6}$`)

// SHAPattern is a full commit id.
var SHAPattern = regexp.MustCompile(`^[0-9a-f]{40}$`)

// Job kinds.
const (
	KindRun = "run"
	KindGen = "gen"
)

// Probe is the response to "probe". Probing also reconciles (docs/SPEC.md §5.3).
type Probe struct {
	Schema         int               `json:"schema"`
	Runner         string            `json:"runner"`  // Version() of the runner that answered
	HostID         string            `json:"host_id"` // random, written once per install (§4)
	BootID         string            `json:"boot_id"`
	Git            string            `json:"git"`   // "git --version" number, such as "2.55.0"
	Tools          map[string]bool   `json:"tools"` // flock, setsid, timeout, base64, sha256sum
	DiskFreeKB     int64             `json:"disk_free_kb"`
	GitHubTokenEnv bool              `json:"github_token_env"` // a token variable is visible to the runner
	QueueDepth     int               `json:"queue_depth"`
	Running        *RunningJob       `json:"running"`
	Refs           map[string]string `json:"refs"`       // branch key → last commit received
	Reconciled     []string          `json:"reconciled"` // ids this probe marked lost
}

// RunningJob is the job that holds the host's lock.
type RunningJob struct {
	ID   string `json:"id"`
	AgeS int64  `json:"age_s"`
}

// SubmitRequest queues a job. The controller chooses ID and Fingerprint
// before it opens the connection, so that a replay is recognised.
type SubmitRequest struct {
	ID          string
	Key         string
	SHA         string
	Fingerprint string // hex sha256 of what defines the job (Fingerprint func)
	Kind        string // KindRun or KindGen
	Prio        int    // 0 to 9, lower runs first
	Timeout     time.Duration
	Cmd         string // run as bash -o pipefail -c Cmd in the worktree
	// Bundle opens the git bundle to send, and gives its size. Nil when the
	// host already has SHA (Probe.Refs). The client may call it again to
	// retry a connection that never started.
	Bundle func() (io.ReadCloser, int64, error)
}

// Submit statuses.
const (
	SubmitAccepted = "accepted" // queued now
	SubmitExists   = "exists"   // same id and fingerprint: the existing job
)

// SubmitResult is the response to "submit".
type SubmitResult struct {
	Schema int    `json:"schema"`
	ID     string `json:"id"`
	Status string `json:"status"`
	State  string `json:"state"`
}

// WaitRequest waits up to Slice (at most MaxWaitSlice) for any of IDs to end.
type WaitRequest struct {
	IDs       []string
	Slice     time.Duration
	All       bool // wait for every job instead of the first
	TailBytes int  // log tail returned with each finished job, at most MaxLogChunk
}

// JobStatus is what the runner knows about one job. Terminal states are never
// rewritten. State is one of the names in internal/job.
type JobStatus struct {
	Schema      int    `json:"schema"`
	ID          string `json:"id"`
	State       string `json:"state"`
	ExitCode    *int   `json:"exit_code"`    // the command's own exit code, once it ran
	FailureKind string `json:"failure_kind"` // user, infra, lost, gate; empty unless failed
	Stage       string `json:"stage"`        // where it stopped, such as "fetch", "verify-sha", "command"
	Reason      string `json:"reason"`       // short text for humans
	SHA         string `json:"sha"`
	HostID      string `json:"host_id"`
	QueuePos    int    `json:"queue_pos"` // 1 is next; 0 when not queued
	StartedAt   string `json:"started_at"`
	EndedAt     string `json:"ended_at"`
	LogSize     int64  `json:"log_size"`
	LogTailB64  string `json:"log_tail_b64"`
	Truncated   bool   `json:"truncated"`        // the log went over MaxLogFile and the job was stopped
	TreeDirty   bool   `json:"tree_dirty_after"` // the command changed tracked files
	PatchSHA256 string `json:"patch_sha256"`     // gen only: sha256 of the patch, once the job succeeded
	PatchSize   int64  `json:"patch_size"`       // gen only: its size in bytes (0 for an empty patch)
}

// WaitResult is the response to "wait".
type WaitResult struct {
	Schema int         `json:"schema"`
	Jobs   []JobStatus `json:"jobs"`
}

// LogRequest reads a job's log from byte Since, at most MaxBytes, cut at the
// last newline. Grep (an extended regular expression) and TailLines filter it.
type LogRequest struct {
	ID        string
	Since     int64
	MaxBytes  int
	Grep      string
	TailLines int
}

// LogChunk is the response to "log".
type LogChunk struct {
	Schema    int    `json:"schema"`
	ID        string `json:"id"`
	State     string `json:"state"`
	DataB64   string `json:"data_b64"`
	Cursor    int64  `json:"cursor"` // pass it back as Since
	Size      int64  `json:"size"`
	Truncated bool   `json:"truncated"` // more data than MaxBytes
}

// Fingerprint identifies what a job does, so that a replayed submit with the
// same id is recognised and a different job under the same id is refused.
func Fingerprint(r SubmitRequest) string {
	h := sha256.New()
	fmt.Fprintf(h, "gatehaul-job-v1\x00%s\x00%s\x00%s\x00%d\x00%d\x00%s",
		r.Kind, r.SHA, r.Key, r.Prio, int64(r.Timeout/time.Second), r.Cmd)
	return hex.EncodeToString(h.Sum(nil))
}

// PatchData is the response to "patch": the patch of a gen job that succeeded,
// computed on the host by "git add -A -N" then "git diff --binary --full-index
// --no-ext-diff --no-textconv --no-renames HEAD" (docs/SPEC.md §5.2 step 7).
// The controller checks SHA256 against the bytes before anything else, then
// sanitises the patch on a tree diff (internal/patch) before applying it.
type PatchData struct {
	Schema  int    `json:"schema"`
	ID      string `json:"id"`
	SHA256  string `json:"sha256"`
	Size    int64  `json:"size"`
	DataB64 string `json:"data_b64"`
}

// ErrorResponse is the JSON of a response whose END rc is not 0.
type ErrorResponse struct {
	Schema int `json:"schema"`
	Error  struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"error"`
}

// Remote error codes. They are stable, like out.Code.
const (
	ErrCodeBadRequest     = "bad_request"
	ErrCodeUnknownJob     = "unknown_job"
	ErrCodeConflict       = "conflict"  // same id, other fingerprint
	ErrCodeNeedFull       = "need_full" // the bundle's prerequisites are missing: send a full bundle
	ErrCodeBundleInvalid  = "bundle_invalid"
	ErrCodeBundleTooLarge = "bundle_too_large"
	ErrCodeSHAMismatch    = "sha_mismatch" // the bundle does not hold the expected commit
	ErrCodeMissingTool    = "missing_tool"
	ErrCodeInstallFailed  = "install_failed"
	ErrCodeNoExec         = "noexec"
	ErrCodeDiskFull       = "disk_full"
	ErrCodeNoPatch        = "no_patch"        // not a gen job, not finished, or it failed
	ErrCodePatchTooLarge  = "patch_too_large" // over MaxPatchBytes
)

// RemoteError is a runner that answered with an ErrorResponse.
type RemoteError struct {
	Code    string
	Message string
}

func (e *RemoteError) Error() string { return fmt.Sprintf("runner: %s: %s", e.Code, e.Message) }

// ErrNotStarted wraps transport failures that happened before the HELLO line,
// after the client's retries: the remote side did nothing.
var ErrNotStarted = errors.New("runner did not start")

// ErrOutcomeUnknown wraps a stream that was cut after HELLO and before END:
// the request may or may not have taken effect.
var ErrOutcomeUnknown = errors.New("outcome unknown")

// ErrProtocol means the runner's output could not be parsed.
var ErrProtocol = errors.New("runner protocol error")

// API is what the controller needs from a runner. Client implements it; tests
// of the controller may fake it.
type API interface {
	Probe(ctx context.Context) (Probe, error)
	Submit(ctx context.Context, r SubmitRequest) (SubmitResult, error)
	Wait(ctx context.Context, r WaitRequest) ([]JobStatus, error)
	Log(ctx context.Context, r LogRequest) (LogChunk, error)
	Cancel(ctx context.Context, id string) (JobStatus, error)
	Patch(ctx context.Context, id string) (PatchData, error)
}
